const res = $input.first().json;
const raw = (typeof res.data === 'string' && res.data) || (typeof res.body === 'string' && res.body) || JSON.stringify(res.data || res.body || '');
const html = String(raw);
const m = html.match(/name=["']csrfmiddlewaretoken["'][^>]*value=["']([^"']+)["']/) || html.match(/value=["']([^"']+)["'][^>]*name=["']csrfmiddlewaretoken["']/);
const sc = (res.headers && (res.headers['set-cookie'] || res.headers['Set-Cookie'])) || [];
const arr = Array.isArray(sc) ? sc : [sc];
const csrfCookie = arr.map(function (c) { return String(c).split(';')[0]; }).filter(function (c) { return c.indexOf('csrftoken=') === 0; })[0];
if (!m || !csrfCookie) { throw new Error('SolarLive login page did not return a security token'); }
let mode = 'daily';
if ($('Mode: Health Check').isExecuted) { mode = 'health'; }
else if ($('Mode: Monthly Report').isExecuted) { mode = 'monthly'; }
return [{ json: { csrfToken: m[1], csrfCookie: csrfCookie, mode: mode } }];

const res = $input.first().json;
const prev = $('Read Login Token').first().json;
const sc = (res.headers && (res.headers['set-cookie'] || res.headers['Set-Cookie'])) || [];
const arr = Array.isArray(sc) ? sc : [sc];
const parts = arr.map(function (c) { return String(c).split(';')[0]; });
const session = parts.filter(function (c) { return c.indexOf('sessionid=') === 0; })[0];
const csrf = parts.filter(function (c) { return c.indexOf('csrftoken=') === 0; })[0] || prev.csrfCookie;
const ok = !!session;
return [{ json: { loginOk: ok, cookie: ok ? session + '; ' + csrf : '', mode: prev.mode, httpStatus: res.statusCode } }];

const PLANTS = [{ id: 446 }, { id: 444 }, { id: 445 }];
const login = $input.first().json;
const mode = login.mode;
const cookie = login.cookie;
const ist = new Date(Date.now() + 19800000);
function md(d) { return (d.getUTCMonth() + 1) + '/' + d.getUTCDate() + '/' + d.getUTCFullYear(); }
const yest = new Date(ist.getTime() - 86400000);
const monthStartYest = new Date(Date.UTC(yest.getUTCFullYear(), yest.getUTCMonth(), 1));
const monthStartBefore = new Date(Date.UTC(yest.getUTCFullYear(), yest.getUTCMonth() - 1, 1));
const prevMonth = new Date(Date.UTC(ist.getUTCFullYear(), ist.getUTCMonth() - 1, 1));
const base = 'https://app.solarlive.in';
const items = [];
function add(kind, p, url) { items.push({ json: { kind: kind, plantId: p.id, url: base + url, cookie: cookie, mode: mode } }); }
PLANTS.forEach(function (p) {
  if (mode === 'daily') {
    add('day', p, '/api/data/?site=' + p.id + '&parameters=INV_PLANT_GENERATION,INV_PLANT_CUF,INV_PLANT_REVENUE&date=' + md(yest));
    add('inv', p, '/api/data/?site=' + p.id + '&parameters=DAILY_KWH&group_by=device&range_type=day&date=' + md(yest));
    add('mtd', p, '/api/data/?site=' + p.id + '&parameters=INV_PLANT_GENERATION&range_type=month&date=' + md(monthStartYest));
    add('alerts', p, '/api/alerts/?site=' + p.id + '&status=open');
    add('trend1', p, '/api/data/?site=' + p.id + '&parameters=INV_PLANT_GENERATION,INV_PLANT_CUF&range_type=month&date=' + md(monthStartYest));
    add('trend0', p, '/api/data/?site=' + p.id + '&parameters=INV_PLANT_GENERATION,INV_PLANT_CUF&range_type=month&date=' + md(monthStartBefore));
  } else if (mode === 'health') {
    add('status', p, '/fetch_data/?parameter=PLANT_DAY_GEN&operation=sum&sites=' + p.id);
    add('alerts', p, '/api/alerts/?site=' + p.id + '&status=open');
  } else {
    add('month', p, '/api/data/?site=' + p.id + '&parameters=INV_PLANT_GENERATION&range_type=month&date=' + md(prevMonth));
  }
});
return items;

const PLANTS = {
  446: { name: 'Agastya Solar (Umarda, Kota)', short: 'Agastya', dc: 1387.1, tariff: 2.88 },
  444: { name: 'White Screen Solar (Dhanpura AG / Magriwada)', short: 'Dhanpura-Magriwada', dc: 2402.4, tariff: 2.91 },
  445: { name: 'White Screen Solar (Nimbaj)', short: 'Nimbaj', dc: 2402.4, tariff: 2.79 }
};
const TARGETS = { 1: 5.0, 2: 5.0, 3: 5.75, 4: 5.75, 5: 5.75, 6: 5.75, 7: 4.25, 8: 4.25, 9: 4.25, 10: 5.0, 11: 5.0, 12: 5.0 };
const ROUTINE_TO = 'recipient@example.com';
const EMERGENCY_TO = 'recipient@example.com';
const TEST_RUN = $execution.mode === 'test';
const MAIL_TO = ROUTINE_TO;
const SUBJ = TEST_RUN ? 'TEST - ' : '';
const reqs = $('Plan Requests').all();
const resp = $input.all();
const mode = reqs.length ? reqs[0].json.mode : 'daily';
const ist = new Date(Date.now() + 19800000);
function pad(n) { return n < 10 ? '0' + n : '' + n; }
function iso(d) { return d.getUTCFullYear() + '-' + pad(d.getUTCMonth() + 1) + '-' + pad(d.getUTCDate()); }
function dmy(d) { return pad(d.getUTCDate()) + '-' + pad(d.getUTCMonth() + 1) + '-' + d.getUTCFullYear(); }
function num(n, dp) { const f = Math.pow(10, dp === undefined ? 0 : dp); return (Math.round(n * f) / f).toLocaleString('en-IN'); }
function series(j, param) { const reps = (j && j.other_reports) || []; const hit = reps.filter(function (x) { return x.parameter === param; })[0]; return hit && hit.reports ? hit.reports : []; }
function lastNum(arr) { let v = null; arr.forEach(function (x) { if (typeof x.value === 'number') { v = x.value; } }); return v; }
const TD = 'style="border:1px solid #999;padding:4px 8px;text-align:right"';
const TDL = 'style="border:1px solid #999;padding:4px 8px;text-align:left"';
const TH = 'style="border:1px solid #999;padding:4px 8px;text-align:center;background:#eee"';
const wrapOpen = '<div style="font-family:Times New Roman,serif;font-size:14px;color:#111;line-height:1.5">';
const data = {};
for (let i = 0; i < resp.length; i++) {
  const r = reqs[i].json;
  if (!data[r.plantId]) { data[r.plantId] = {}; }
  data[r.plantId][r.kind] = resp[i].json;
}
const ids = Object.keys(PLANTS);
const out = [];

if (mode === 'health') {
  const sd = $getWorkflowStaticData('global');
  const firstRun = !sd.seenAlerts;
  if (!sd.seenAlerts) { sd.seenAlerts = []; }
  if (!sd.lastGen) { sd.lastGen = {}; }
  const hour = ist.getUTCHours();
  const todayIso = iso(ist);
  const issues = [];
  ids.forEach(function (id) {
    const P = PLANTS[id];
    const d = data[id] || {};
    const rep = d.status && d.status.reports && d.status.reports[0];
    if (!rep) { issues.push(P.short + ': no data received from SolarLive'); return; }
    if (rep.status !== 'active') { issues.push(P.short + ': plant status is ' + rep.status); }
    const gen = rep.value;
    const prev = sd.lastGen[id];
    if (hour >= 10 && hour <= 15) {
      if (gen < 1) {
        issues.push(P.short + ': no generation recorded today at ' + pad(hour) + ':00');
      } else if (prev && prev.date === todayIso && (Date.now() - prev.ts) >= 5400000 && (gen - prev.gen) < 5) {
        issues.push(P.short + ': generation has not increased since the last check (' + num(gen, 1) + ' kWh today)');
      }
    }
    sd.lastGen[id] = { date: todayIso, gen: gen, ts: Date.now() };
    const alerts = (d.alerts && d.alerts.results) || [];
    alerts.forEach(function (a) {
      if (sd.seenAlerts.indexOf(a.id) === -1) {
        sd.seenAlerts.push(a.id);
        if (!firstRun) { issues.push(P.short + ': new alert - ' + a.alert + ' (' + a.device + ', since ' + a.start_time_str + ')'); }
      }
    });
  });
  if (sd.seenAlerts.length > 300) { sd.seenAlerts = sd.seenAlerts.slice(-200); }
  if (!issues.length) { return []; }
  let html = wrapOpen + '<p>The following need your attention (checked ' + dmy(ist) + ' ' + pad(hour) + ':' + pad(ist.getUTCMinutes()) + ' IST):</p><ul>';
  issues.forEach(function (t) { html += '<li>' + t + '</li>'; });
  html += '</ul><p>Please check SolarLive for details.</p></div>';
  out.push({ json: { type: 'emergency', to: EMERGENCY_TO, subject: 'Emergency: Need your attention - SolarLive (' + dmy(ist) + ' ' + pad(hour) + ':00)', html: html } });
  return out;
}

if (mode === 'daily') {
  const y = new Date(ist.getTime() - 86400000);
  const yIso = iso(y);
  const yDay = y.getUTCDate();
  const tgt = TARGETS[y.getUTCMonth() + 1];
  let html = wrapOpen + '<p>Daily generation summary for <b>' + dmy(y) + '</b>. All capacities are DC. Target this month: <b>' + tgt + ' kWh per kWp per day</b> (winter Nov-Feb 5.0, Mar-Jun 5.75, monsoon Jul-Sep 4.25, Oct 5.0).</p>';
  let totGen = 0;
  let totExp = 0;
  let totMtd = 0;
  let totMtdTarget = 0;
  let totDayTarget = 0;
  ids.forEach(function (id) {
    const P = PLANTS[id];
    const kw = P.dc;
    const d = data[id] || {};
    const gen = lastNum(series(d.day, 'INV_PLANT_GENERATION'));
    const cuf = lastNum(series(d.day, 'INV_PLANT_CUF'));
    const rev = lastNum(series(d.day, 'INV_PLANT_REVENUE'));
    const exp = gen === null ? null : gen * P.tariff;
    const invs = ((d.inv && d.inv.other_reports) || []).map(function (x) {
      let m = 0;
      (x.reports || []).forEach(function (r) { if (String(r.time).indexOf(yIso) === 0 && typeof r.value === 'number' && r.value > m) { m = r.value; } });
      return { dev: x.device, kwh: m };
    });
    const avg = invs.length ? invs.reduce(function (s, x) { return s + x.kwh; }, 0) / invs.length : 0;
    const weak = invs.filter(function (x) { return avg > 0 && x.kwh < avg * 0.85; });
    const mrows = series(d.mtd, 'INV_PLANT_GENERATION').filter(function (r) { return String(r.time).slice(0, 10) <= yIso; });
    let mtd = 0;
    let have = 0;
    mrows.forEach(function (r) { if (typeof r.value === 'number') { mtd += r.value; have += 1; } });
    const missing = yDay - have;
    const mtdTarget = kw * tgt * yDay;
    const alerts = (d.alerts && d.alerts.results) || [];
    if (gen !== null) { totGen += gen; totExp += exp; }
    totMtd += mtd;
    totMtdTarget += mtdTarget;
    totDayTarget += kw * tgt;
    html += '<p style="margin-bottom:2px"><b>' + P.name + '</b> (' + num(P.dc, 1) + ' kWp DC, tariff Rs. ' + P.tariff + '/kWh)</p>';
    if (gen === null) {
      html += '<p>No generation data received for this day.</p>';
    } else {
      html += '<table style="border-collapse:collapse"><tr><td ' + TDL + '>Generation</td><td ' + TD + '>' + num(gen, 1) + ' kWh (' + num(gen / kw, 2) + ' kWh per kWp; target ' + num(kw * tgt) + ' kWh; ' + num(gen / (kw * tgt) * 100) + '% of target achieved)</td></tr>';
      html += '<tr><td ' + TDL + '>CUF</td><td ' + TD + '>' + (cuf === null ? '-' : num(cuf, 2) + ' %') + '</td></tr>';
      html += '<tr><td ' + TDL + '>Expected earnings at PPA tariff</td><td ' + TD + '>Rs. ' + num(exp) + '</td></tr>';
      html += '<tr><td ' + TDL + '>Month to date</td><td ' + TD + '>' + num(mtd, 1) + ' kWh (' + num(mtd / kw / yDay, 2) + ' kWh per kWp per day) against target ' + num(mtdTarget) + ' kWh = ' + num(mtd / mtdTarget * 100) + '% (Rs. ' + num(mtd * P.tariff) + ')' + (missing > 0 ? ' - ' + missing + ' day(s) without SolarLive data' : '') + '</td></tr></table>';
    }
    if (invs.length) {
      html += '<p style="margin:4px 0">Inverters (kWh): ' + invs.map(function (x) { return x.dev + ' ' + num(x.kwh); }).join(', ') + '</p>';
      if (weak.length) { html += '<p style="margin:4px 0"><b>Below 85% of inverter average:</b> ' + weak.map(function (x) { return x.dev; }).join(', ') + '</p>'; }
    }
    if (alerts.length) {
      html += '<p style="margin:4px 0"><b>Open alerts (' + alerts.length + '):</b></p><ul style="margin-top:0">';
      alerts.forEach(function (a) { html += '<li>' + a.alert + ' (' + a.device + ') since ' + a.start_time_str + '</li>'; });
      html += '</ul>';
    } else {
      html += '<p style="margin:4px 0">No open alerts.</p>';
    }
    if (!TEST_RUN) {
      out.push({ json: { type: 'sheet_row', sheet: P.short, Date: dmy(y), Plant: P.name, Generation_kWh: gen, CUF_pct: cuf, Tariff: P.tariff, Expected_Earnings_INR: exp === null ? null : Math.round(exp), SolarLive_Revenue_INR: rev, Inverter_kWh: invs.map(function (x) { return x.dev + ':' + Math.round(x.kwh); }).join('; '), Open_Alerts: alerts.length, MTD_kWh: Math.round(mtd) } });
    }
  });
  html += '<p><b>All plants:</b> yesterday ' + num(totGen, 1) + ' kWh against target ' + num(totDayTarget) + ' kWh (' + num(totGen / totDayTarget * 100) + '%), expected earnings Rs. ' + num(totExp) + '.<br><b>All plants, month to date:</b> ' + num(totMtd) + ' kWh against target ' + num(totMtdTarget) + ' kWh (' + num(totMtd / totMtdTarget * 100) + '%).</p>';
  const TREND_ORDER = ['445', '444', '446'];
  const TREND_HEAD = { 445: 'Nimbaj', 444: 'Magriwada', 446: 'Umarda' };
  const trend = {};
  TREND_ORDER.forEach(function (id) {
    const d = data[id] || {};
    const m = {};
    ['trend0', 'trend1'].forEach(function (k) {
      series(d[k], 'INV_PLANT_GENERATION').forEach(function (r) { if (typeof r.value === 'number') { const key = String(r.time).slice(0, 10); m[key] = m[key] || {}; m[key].gen = r.value; } });
      series(d[k], 'INV_PLANT_CUF').forEach(function (r) { if (typeof r.value === 'number') { const key = String(r.time).slice(0, 10); m[key] = m[key] || {}; m[key].cuf = r.value; } });
    });
    trend[id] = m;
  });
  const tot = {};
  TREND_ORDER.forEach(function (id) { tot[id] = { gen: 0, cufSum: 0, n: 0 }; });
  let th = '<p style="margin-bottom:2px"><b>Last 15 days comparison</b></p><table style="border-collapse:collapse"><tr><th ' + TH + ' rowspan="2">Date</th>';
  TREND_ORDER.forEach(function (id) { th += '<th ' + TH + ' colspan="2">' + TREND_HEAD[id] + '</th>'; });
  th += '</tr><tr>';
  TREND_ORDER.forEach(function () { th += '<th ' + TH + '>Generation (kWh)</th><th ' + TH + '>CUF (%)</th>'; });
  th += '</tr>';
  for (let k = 0; k < 15; k++) {
    const dd = new Date(y.getTime() - k * 86400000);
    const key = iso(dd);
    th += '<tr><td ' + TDL + '>' + dmy(dd) + '</td>';
    TREND_ORDER.forEach(function (id) {
      const v = (trend[id] || {})[key] || {};
      th += '<td ' + TD + '>' + (typeof v.gen === 'number' ? num(v.gen, 1) : '-') + '</td><td ' + TD + '>' + (typeof v.cuf === 'number' ? num(v.cuf, 2) : '-') + '</td>';
      if (typeof v.gen === 'number') { tot[id].gen += v.gen; }
      if (typeof v.cuf === 'number') { tot[id].cufSum += v.cuf; tot[id].n += 1; }
    });
    th += '</tr>';
  }
  th += '<tr><td ' + TDL + '><b>Total / Avg CUF</b></td>';
  TREND_ORDER.forEach(function (id) { th += '<td ' + TD + '><b>' + num(tot[id].gen, 1) + '</b></td><td ' + TD + '><b>' + (tot[id].n ? num(tot[id].cufSum / tot[id].n, 2) : '-') + '</b></td>'; });
  th += '</tr></table><p style="margin:4px 0">Latest day first. Days without SolarLive data are shown as -. CUF is as reported by SolarLive.</p>';
  html += th + '</div>';
  out.unshift({ json: { type: 'routine_email', to: MAIL_TO, subject: SUBJ + 'Solar generation summary - ' + dmy(y), html: html } });
  return out;
}

const pm = new Date(Date.UTC(ist.getUTCFullYear(), ist.getUTCMonth() - 1, 1));
const daysInMonth = new Date(Date.UTC(pm.getUTCFullYear(), pm.getUTCMonth() + 1, 0)).getUTCDate();
const monthName = ['January', 'February', 'March', 'April', 'May', 'June', 'July', 'August', 'September', 'October', 'November', 'December'][pm.getUTCMonth()];
const mtgt = TARGETS[pm.getUTCMonth() + 1];
let html = wrapOpen + '<p>Monthly generation report for <b>' + monthName + ' ' + pm.getUTCFullYear() + '</b>. All capacities are DC. Target: <b>' + mtgt + ' kWh per kWp per day</b> (winter Nov-Feb 5.0, Mar-Jun 5.75, monsoon Jul-Sep 4.25, Oct 5.0).</p>';
html += '<table style="border-collapse:collapse"><tr><th ' + TDL + '>Plant</th><th ' + TD + '>Generation (kWh)</th><th ' + TD + '>Days with data</th><th ' + TD + '>kWh per kWp per day</th><th ' + TD + '>Target for days with data (kWh)</th><th ' + TD + '>% of target</th><th ' + TD + '>Best day</th><th ' + TD + '>Lowest day</th><th ' + TD + '>Expected earnings (Rs.)</th></tr>';
let gTot = 0;
let gExp = 0;
let gTarget = 0;
ids.forEach(function (id) {
  const P = PLANTS[id];
  const kw = P.dc;
  const rows = series((data[id] || {}).month, 'INV_PLANT_GENERATION').filter(function (r) { return typeof r.value === 'number'; });
  let tot = 0;
  let best = null;
  let low = null;
  rows.forEach(function (r) {
    tot += r.value;
    if (!best || r.value > best.value) { best = r; }
    if (!low || r.value < low.value) { low = r; }
  });
  const exp = tot * P.tariff;
  const target = kw * mtgt * rows.length;
  gTot += tot;
  gExp += exp;
  gTarget += target;
  html += '<tr><td ' + TDL + '>' + P.short + ' (Rs. ' + P.tariff + ')</td><td ' + TD + '>' + num(tot) + '</td><td ' + TD + '>' + rows.length + ' of ' + daysInMonth + '</td><td ' + TD + '>' + (rows.length ? num(tot / rows.length / kw, 2) : '-') + '</td><td ' + TD + '>' + num(target) + '</td><td ' + TD + '>' + num(tot / target * 100) + '%</td><td ' + TD + '>' + (best ? num(best.value) + ' (' + String(best.time).slice(8, 10) + ')' : '-') + '</td><td ' + TD + '>' + (low ? num(low.value) + ' (' + String(low.time).slice(8, 10) + ')' : '-') + '</td><td ' + TD + '>' + num(exp) + '</td></tr>';
});
html += '<tr><td ' + TDL + '><b>Total</b></td><td ' + TD + '><b>' + num(gTot) + '</b></td><td ' + TD + '></td><td ' + TD + '></td><td ' + TD + '><b>' + num(gTarget) + '</b></td><td ' + TD + '><b>' + num(gTot / gTarget * 100) + '%</b></td><td ' + TD + '></td><td ' + TD + '></td><td ' + TD + '><b>' + num(gExp) + '</b></td></tr></table>';
html += '<p>The target for each plant is its DC capacity (2,402.4 kWp for Nimbaj and Magriwada, 1,387.1 kWp for Agastya) multiplied by the monthly target per kWp per day and the number of days SolarLive has data for, so missing days do not lower the percentage. Generation for the missing days is not included in the totals. Expected earnings are generation multiplied by the PPA tariff. The Discom bill is based on exported units, which are normally slightly lower than generation.</p></div>';
out.push({ json: { type: 'routine_email', to: MAIL_TO, subject: SUBJ + 'Monthly solar report - ' + monthName + ' ' + pm.getUTCFullYear(), html: html } });
return out;
